/**
 * Genera un mapa urbano procedimental integrando assets arquitectónicos modernos.
 * Implementa una cuadrícula dinámica basada en densidad para poblar parcelas 
 * de manera automática evitando colisiones con calzadas e hitos.
 */
async function buildTiltedTowers(originX = 0, originY = 0, originZ = 0, options = {}) {
    const mapWidth = options.mapWidth || 128;
    const mapHeight = options.mapHeight || 48;
    const mapDepth = options.mapDepth || 128;
    const cityBaseY = options.cityBaseY || 12;
    const density = options.density !== undefined ? options.density : 0.85;

    // Catálogo de materiales actualizado con los nuevos assets urbanos
    const roadMat = options.roadMat || 'asphalt';
    const roadMarkMat = options.roadMarkMat || 'white_whool';
    const manholeMat = options.manholeMat || 'manhole';
    const sidewalkMat = options.sidewalkMat || 'pavement';
    const curbMat = options.curbMat || 'curb';
    const brickMat = options.brickMat || 'ladrillo';
    const stoneBrickMat = options.stoneBrickMat || 'ladrillo_piedra';
    const concreteMat = options.concreteMat || 'concrete';
    const darkGraniteMat = options.darkGraniteMat || 'dark_granite';
    const glassMat = options.glassMat || 'window_night';
    const roofMat = options.roofMat || 'corrugated_metal';
    const woodMat = options.woodMat || 'tablones';
    const clockMat = options.clockMat || 'diana';
    const urbanGrassMat = options.urbanGrassMat || 'urban_grass';
    const planterMat = options.planterMat || 'mulch_planter';
    const grassMat = options.grassMat || 'hierba'; // Periferia natural
    const rockMat = options.rockMat || 'roca';
    const dirtMat = options.dirtMat || 'tierra';
    const logMat = options.logMat || 'tronco';
    const leafMat = options.leafMat || 'leaves';
    const awningRed = 'red_concrete';
    const awningWhite = 'white_whool';

    // Precarga de materiales en el motor
    if (typeof game !== 'undefined' && game.addMaterial) {
        const materialsToLoad = [
            roadMat, roadMarkMat, manholeMat, sidewalkMat, curbMat, 
            brickMat, stoneBrickMat, concreteMat, darkGraniteMat, glassMat, 
            roofMat, woodMat, clockMat, urbanGrassMat, planterMat, 
            grassMat, rockMat, dirtMat, logMat, leafMat
        ];
        await Promise.all(materialsToLoad.map(mat => game.addMaterial(mat).catch(() => null)));
    }

    if (typeof beginBatch === 'function') beginBatch();

    // 1. TOPOGRAFÍA
    function getTerrainHeight(x, z) {
        const distFromCenterX = Math.abs(x - mapWidth / 2) / (mapWidth / 2);
        const distFromCenterZ = Math.abs(z - mapDepth / 2) / (mapDepth / 2);
        const edgeDist = Math.max(distFromCenterX, distFromCenterZ);

        if (edgeDist < 0.65) return cityBaseY;

        const factor = (edgeDist - 0.65) / 0.35;
        const cliffNoise = Math.sin(x * 0.15) * 2.5 + Math.cos(z * 0.15) * 2.5;
        const elevation = Math.pow(factor, 2.0) * (mapHeight - cityBaseY - 4) + cliffNoise;
        return Math.min(mapHeight - 2, Math.floor(cityBaseY + Math.max(0, elevation)));
    }

    // 2. URBANIZACIÓN Y CALLES
    const cityBounds = {
        minX: Math.floor(mapWidth * 0.15),
        maxX: Math.floor(mapWidth * 0.85),
        minZ: Math.floor(mapDepth * 0.15),
        maxZ: Math.floor(mapDepth * 0.85)
    };

    const roadsX = [Math.floor(mapWidth * 0.35), Math.floor(mapWidth * 0.65)];
    const roadsZ = [Math.floor(mapDepth * 0.35), Math.floor(mapDepth * 0.65)];
    const roadWidth = 8; 
    const halfRoad = Math.floor(roadWidth / 2);

    for (let x = 0; x < mapWidth; x++) {
        for (let z = 0; z < mapDepth; z++) {
            const surfaceY = getTerrainHeight(x, z);
            const inCity = (x >= cityBounds.minX && x <= cityBounds.maxX && z >= cityBounds.minZ && z <= cityBounds.maxZ);

            // Detección de calzada y bordillo
            const onRoadX = inCity && roadsX.some(rx => Math.abs(x - rx) <= halfRoad);
            const onRoadZ = inCity && roadsZ.some(rz => Math.abs(z - rz) <= halfRoad);
            const isRoad = onRoadX || onRoadZ;

            const isCurbX = inCity && !isRoad && roadsX.some(rx => Math.abs(x - rx) === halfRoad + 1);
            const isCurbZ = inCity && !isRoad && roadsZ.some(rz => Math.abs(z - rz) === halfRoad + 1);
            const isCurb = isCurbX || isCurbZ;

            for (let y = 0; y <= surfaceY; y++) {
                const gx = originX + x;
                const gy = originY + y;
                const gz = originZ + z;

                if (y === surfaceY) {
                    if (isRoad) {
                        const isCenterLineX = onRoadX && !onRoadZ && roadsX.some(rx => x === rx) && (z % 4 < 2);
                        const isCenterLineZ = onRoadZ && !onRoadX && roadsZ.some(rz => z === rz) && (x % 4 < 2);
                        // Frecuencia de alcantarillas en los bordes de la calzada
                        const isManhole = !isCenterLineX && !isCenterLineZ && ((x + z) % 16 === 0);

                        if (isCenterLineX || isCenterLineZ) setVoxel(gx, gy, gz, roadMarkMat);
                        else if (isManhole) setVoxel(gx, gy, gz, manholeMat);
                        else setVoxel(gx, gy, gz, roadMat);
                    } else if (isCurb) {
                        setVoxel(gx, gy, gz, curbMat);
                    } else if (inCity) {
                        setVoxel(gx, gy, gz, sidewalkMat);
                    } else {
                        const hNext = getTerrainHeight(Math.min(x + 1, mapWidth - 1), z);
                        const slope = Math.abs(surfaceY - hNext);
                        setVoxel(gx, gy, gz, slope >= 3 ? rockMat : grassMat);
                    }
                } else if (y >= surfaceY - 3) {
                    setVoxel(gx, gy, gz, inCity ? dirtMat : rockMat);
                } else {
                    setVoxel(gx, gy, gz, y === 0 ? 'obsidiana' : rockMat);
                }
            }
        }
    }

    // 3. GENERADORES ESTRUCTURALES
    function buildBuilding(bx, bz, width, depth, height, wallMat, decoMat, hasAwnings = false) {
        for (let y = 1; y <= height; y++) {
            const vy = originY + cityBaseY + y;
            for (let x = 0; x < width; x++) {
                for (let z = 0; z < depth; z++) {
                    const vx = originX + bx + x;
                    const vz = originZ + bz + z;
                    const isPerimeter = (x === 0 || x === width - 1 || z === 0 || z === depth - 1);
                    const isCorner = (x === 0 || x === width - 1) && (z === 0 || z === depth - 1);

                    if (y === height) {
                        setVoxel(vx, vy, vz, isPerimeter ? decoMat : roofMat);
                    } else if (isPerimeter) {
                        if (isCorner) {
                            setVoxel(vx, vy, vz, decoMat);
                        } else {
                            const isWindow = (y % 4 === 2 || y % 4 === 3) && ((x % 3 === 1) || (z % 3 === 1)) && y < height - 1 && y > 1;
                            setVoxel(vx, vy, vz, isWindow ? glassMat : wallMat);
                        }
                    } else if (y % 4 === 0) {
                        setVoxel(vx, vy, vz, woodMat);
                    }
                }
            }
        }
        if (hasAwnings) {
            const awningY = originY + cityBaseY + 3;
            for (let x = 1; x < width - 1; x++) {
                setVoxel(originX + bx + x, awningY, originZ + bz - 1, x % 2 === 0 ? awningRed : awningWhite);
            }
        }
    }

    function buildClockTower(bx, bz) {
        const towerHeight = 28;
        const size = 6;
        for (let y = 1; y <= towerHeight; y++) {
            const vy = originY + cityBaseY + y;
            for (let x = 0; x < size; x++) {
                for (let z = 0; z < size; z++) {
                    const vx = originX + bx + x;
                    const vz = originZ + bz + z;
                    const isPerimeter = (x === 0 || x === size - 1 || z === 0 || z === size - 1);
                    const isCorner = (x === 0 || x === size - 1) && (z === 0 || z === size - 1);

                    if (isPerimeter) {
                        if (y === towerHeight - 3 && !isCorner) {
                            setVoxel(vx, vy, vz, clockMat);
                        } else if (isCorner || y <= 3 || y >= towerHeight - 5) {
                            setVoxel(vx, vy, vz, darkGraniteMat);
                        } else {
                            setVoxel(vx, vy, vz, concreteMat);
                        }
                    }
                }
            }
        }
        const roofBaseY = originY + cityBaseY + towerHeight + 1;
        for (let r = 0; r <= 3; r++) {
            for (let x = r; x < size - r; x++) {
                for (let z = r; z < size - r; z++) {
                    setVoxel(originX + bx + x, roofBaseY + r, originZ + bz + z, roofMat);
                }
            }
        }
    }

    function buildSunkenPlaza(bx, bz, width, depth) {
        const floorY = originY + cityBaseY - 3;
        for (let x = 0; x < width; x++) {
            for (let z = 0; z < depth; z++) {
                const vx = originX + bx + x;
                const vz = originZ + bz + z;

                for(let y = cityBaseY; y > floorY; y--) setVoxel(vx, originY + y, vz, null); 

                const isPerimeter = (x === 0 || x === width - 1 || z === 0 || z === depth - 1);
                for (let y = floorY; y <= cityBaseY; y++) {
                    if (y === floorY) setVoxel(vx, originY + y, vz, sidewalkMat);
                    else if (isPerimeter) setVoxel(vx, originY + y, vz, concreteMat);
                }
            }
        }
        // Base de césped en el centro de la plaza
        for (let x = 4; x < width - 4; x++) {
            for (let z = 4; z < depth - 4; z++) {
                setVoxel(originX + bx + x, floorY, originZ + bz + z, urbanGrassMat);
            }
        }
    }

    function buildPineTree(px, pz, trunkH = 8) {
        const topY = originY + cityBaseY + 1;
        setVoxel(originX + px, topY - 1, originZ + pz, planterMat); // Aplicar alcorque en la base

        for (let th = 0; th < trunkH; th++) setVoxel(originX + px, topY + th, originZ + pz, logMat);
        const leafTop = topY + trunkH;
        setVoxel(originX + px, leafTop + 1, originZ + pz, leafMat);
        const layers = [{r: 1, yOff: 0}, {r: 2, yOff: -1}, {r: 1, yOff: -2}, {r: 3, yOff: -3}, {r: 2, yOff: -4}];
        for (const layer of layers) {
            for (let ox = -layer.r; ox <= layer.r; ox++) {
                for (let oz = -layer.r; oz <= layer.r; oz++) {
                    if (Math.abs(ox) === layer.r && Math.abs(oz) === layer.r) continue;
                    setVoxel(originX + px + ox, leafTop + layer.yOff, originZ + pz + oz, leafMat);
                }
            }
        }
    }

    // 4. PLANIFICACIÓN Y GENERACIÓN PROCEDURAL (ZONING)
    const wallMats = [brickMat, concreteMat, darkGraniteMat, stoneBrickMat];
    const decoMats = [darkGraniteMat, concreteMat, stoneBrickMat, brickMat];
    const blockSize = 18;

    const fixedLandmarks = [
        { x: roadsX[0] + halfRoad + 2, z: roadsZ[0] + halfRoad + 2, w: 8, d: 8, type: 'clock' },
        { x: roadsX[0] + halfRoad + 2, z: cityBounds.minZ + 2, w: 18, d: 16, type: 'plaza' }
    ];

    function checkCollision(bx, bz, bw, bd) {
        if (roadsX.some(rx => bx < rx + halfRoad + 2 && bx + bw > rx - halfRoad - 2)) return true;
        if (roadsZ.some(rz => bz < rz + halfRoad + 2 && bz + bd > rz - halfRoad - 2)) return true;
        for (let lm of fixedLandmarks) {
            if (bx < lm.x + lm.w + 2 && bx + bw > lm.x - 2 && bz < lm.z + lm.d + 2 && bz + bd > lm.z - 2) return true;
        }
        return false;
    }

    buildClockTower(fixedLandmarks[0].x, fixedLandmarks[0].z);
    buildSunkenPlaza(fixedLandmarks[1].x, fixedLandmarks[1].z, fixedLandmarks[1].w, fixedLandmarks[1].d);

    for (let bx = cityBounds.minX + 2; bx < cityBounds.maxX - 14; bx += blockSize) {
        for (let bz = cityBounds.minZ + 2; bz < cityBounds.maxZ - 14; bz += blockSize) {

            const rng = Math.abs(Math.sin(bx * 12.9898 + bz * 78.233)) * 43758.5453;
            const val = rng - Math.floor(rng);

            if (val <= density) {
                const w = 10 + Math.floor((val * 10) % 5);
                const d = 10 + Math.floor((val * 20) % 5);
                const h = 12 + Math.floor((val * 30) % 14);

                if (!checkCollision(bx, bz, w, d)) {
                    const wMat = wallMats[Math.floor(val * 40) % wallMats.length];
                    const dMat = decoMats[Math.floor(val * 50) % decoMats.length];
                    const hasAwning = (val > 0.5);

                    buildBuilding(bx, bz, w, d, h, wMat, dMat, hasAwning);
                }
            } else if (val > 0.8 && !checkCollision(bx, bz, 6, 6)) {
                buildPineTree(bx + 4, bz + 4, 7 + Math.floor(val * 10) % 3);
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();
}

// --------------------------------------------------------------------------
// EJECUCIÓN Y GENERACIÓN DE ENTORNO
// --------------------------------------------------------------------------

await game.wipeMap();
const [mapWidth, mapHeight, mapDepth] = game.worldSize.split('×').map(Number);

console.log(`Generando Tilted Towers Procedural en mapa ${mapWidth}x${mapDepth}...`);

// Pasamos explícitamente los nombres de los nuevos materiales configurados en tu entorno
await buildTiltedTowers(0, 0, 0, {
    mapWidth: mapWidth,
    mapHeight: mapHeight,
    mapDepth: mapDepth,
    density: 0.9,
    roadMat: "asphalt",
    roadMarkMat: "white_whool",
    manholeMat: "manhole",
    sidewalkMat: "pavement",
    curbMat: "curb",
    concreteMat: "concrete",
    darkGraniteMat: "dark_granite",
    glassMat: "window_night",
    roofMat: "corrugated_metal",
    urbanGrassMat: "urban_grass",
    planterMat: "mulch_planter",
    brickMat: "ladrillo",
    stoneBrickMat: "ladrillo_piedra",
    grassMat: "hierba",
    dirtMat: "tierra",
    rockMat: "roca",
    logMat: "tronco",
    leafMat: "leaves",
    cityBaseY: 12 
});

console.log("Añadiendo nubes...");
game.snippet("nubes-altas");
console.log("Generación procedural completada.");
